ALTER TABLE public.club_waitlist ADD COLUMN phone text, ADD COLUMN club_role text, ADD COLUMN needs text[] NOT NULL DEFAULT '{}', ADD COLUMN message text;
ALTER TABLE public.club_waitlist ADD CONSTRAINT club_waitlist_phone_length CHECK (phone IS NULL OR length(phone) <= 30), ADD CONSTRAINT club_waitlist_role_length CHECK (club_role IS NULL OR length(club_role) <= 100), ADD CONSTRAINT club_waitlist_message_length CHECK (message IS NULL OR length(message) <= 5000), ADD CONSTRAINT club_waitlist_needs_values CHECK (needs <@ ARRAY['gestion des adhérents','inscriptions en ligne','communication','visibilité']::text[]);
